package org.springframework.samples.petclinic.service;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Business rule: an owner's {@code membershipTier} is {@code SILVER} when it has no namesakes
 * (namesakeCount is 0) and an email is present, and {@code BRONZE} otherwise. Kept as a small,
 * self-contained unit so the rule can be applied from the read flow without adding complexity to
 * the mapper, controller, or service.
 */
public final class OwnerMembershipTierPolicy {

    private OwnerMembershipTierPolicy() {
    }

    /**
     * Derive the {@code membershipTier} for the given owner.
     *
     * @param owner the owner whose membership tier to derive
     * @return {@code "SILVER"} when the owner has no namesakes and an email, otherwise {@code "BRONZE"}
     */
    public static String membershipTier(Owner owner) {
        Integer namesakeCount = owner.getNamesakeCount();
        boolean silver = namesakeCount != null && namesakeCount == 0
            && owner.getEmail() != null && !owner.getEmail().isEmpty();
        return silver ? "SILVER" : "BRONZE";
    }
}
package org.springframework.samples.petclinic.service;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Business rule: on creation an owner records its {@code namesakeCount}, the number of existing
 * owners that already share the same first and last name (compared case-insensitively) at the
 * moment before this owner is created. Kept as a small, self-contained unit so the rule can be
 * applied from the create flow without adding complexity to the controller or service.
 */
public final class OwnerNamesakePolicy {

    private OwnerNamesakePolicy() {
    }

    /**
     * Record the {@code namesakeCount} for a newly created owner.
     *
     * @param clinicService source of the existing owners
     * @param owner         the owner being created
     */
    public static void assignNamesakeCount(ClinicService clinicService, Owner owner) {
        String firstName = owner.getFirstName();
        String lastName = owner.getLastName();
        int count = 0;
        for (Owner existing : clinicService.findAllOwners()) {
            if (firstName.equalsIgnoreCase(existing.getFirstName())
                && lastName.equalsIgnoreCase(existing.getLastName())) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }
}
package org.springframework.samples.petclinic.service;

import java.time.LocalDate;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Business rule: an owner's {@code membershipNumber} is derived as
 * {@code <customerCode>-M<YY>}, where YY is the last two digits of the registration-date
 * year (e.g. {@code SMI-0007-M26}). Kept as a small, self-contained unit so the rule can be
 * applied from the read flow without adding complexity to the mapper, controller, or service.
 */
public final class OwnerMembershipPolicy {

    private OwnerMembershipPolicy() {
    }

    /**
     * Derive the {@code membershipNumber} for the given owner, or {@code null} when the
     * customer code or registration date it is built from is not yet available.
     *
     * @param owner the owner whose membership number to derive
     * @return the membership number, or {@code null} if it cannot be derived
     */
    public static String membershipNumber(Owner owner) {
        String customerCode = owner.getCustomerCode();
        LocalDate registrationDate = owner.getRegistrationDate();
        if (customerCode == null || registrationDate == null) {
            return null;
        }
        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
    }
}

